// Prefix Assembler (TOKENKILLER) — S0..PAD frozen, S3 volatile last.
const PREFIX = "S0 You are the Valuation analyst. Output an offer RANGE only, never a firm number. Internal advisory only; never shown to seller. Concise reasoning.\nS1 METHOD: ARV from best comps (recency<=90d, <=1mi, similar sqft/beds). repair_band light($15-25/sqft)/moderate($25-45)/heavy($45-75); pick most_likely from self_rated_condition + disclosed_issues (excellent->light, good->light-moderate, fair->moderate, poor->moderate-heavy, severe->heavy; foundation/fire/water_mold never below moderate, foundation/fire lean heavy; if condition absent assume moderate + flag 'condition unconfirmed'). MAO = ARV*(0.60..0.70) - repair_band - holding/closing; trend cooling->0.60 flat->0.65 rising->0.70; nudge -0.05 (floor 0.58) if poor/severe or major issue disclosed. Band is 0.60-0.70, NEVER above 0.70. OUTPUT ONLY JSON: {arv_estimate,repair_band:{low,high,most_likely},offer_range:{low,high},confidence,rationale,comps_used[],flags[]}. <3 comps => confidence=low, widen, flag 'thin comps'. Never invent comps.\nPAD ---- alignment pad ----";
const src = $input.first().json;
const trim = (src.comps||[]).slice(0,6).map(c=>({p:Math.round(c.sold_price||c.p||0),d:c.sold_date||c.d,sqft:c.sqft,bd:c.beds||c.bd,ba:c.baths||c.ba,mi:+(c.distance_mi||c.mi||0).toFixed(1)}));
const v = { address: src.address, subject: src.subject||{}, comps: trim, market: src.market||{}, self_rated_condition: src.self_rated_condition, disclosed_issues: src.disclosed_issues||[], disclosure_text: src.disclosure_text };
return [{ json: { body: {
  model: $env.DEEPSEEK_MODEL,
  temperature: 0,
  max_tokens: 700,
  messages: [
    { role: 'system', content: PREFIX },
    { role: 'user',   content: JSON.stringify(v) }
  ]
}, _prefix_bytes: PREFIX.length } }];

const r = $input.first().json;
const u = r.usage || {};
const hit = u.prompt_cache_hit_tokens || 0, miss = u.prompt_cache_miss_tokens || 0;
const ratio = (hit+miss) ? hit/(hit+miss) : 0;
let t = (r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '{}';
let out; try { out = JSON.parse(t.replace(/```json|```/g,'').trim()); } catch(e){ out = { _parse_error:true }; }
out._cache = { hit, miss, ratio: +ratio.toFixed(4), ok: ratio >= 0.97 };
if(!out._cache.ok) console.warn('TOKENKILLER: cache ratio below floor', out._cache);
return [{ json: out }];
